# ---------- file list into the appendix ----------
rows = []
for sub in sorted(os.listdir(pk)):
    if sub.startswith('06'):
        continue
    for f in sorted(glob.glob(pk + '\\' + sub + '\\*')):
        rows.append((sub + '/' + os.path.basename(f), '%.2f' % (os.path.getsize(f) / 1e6), sha(f)[:16]))
fl = '| קובץ | MB | SHA-256 (16 ראשונים) |\n| --- | --- | --- |\n' + '\n'.join('| %s | %s | %s |' % r for r in rows) + '\n\nתיקיית `06 - מסמכי הפרסום` מכילה עותקים של המסמכים המפורסמים (לא נכללים ברשימה כי הם עשויים להתעדכן).'
ap = open(ap_path, encoding='utf-8').read()
if '__FILELIST__' in ap:
    ap = ap.replace('__FILELIST__', fl)
note = '**הערה:** שורות PM2.5 של 2024 מוצגות לשקיפות בלבד. בטבלה 20 בדוח 2024 השמות מוסטים בשורה אחת ביחס לערכים (ראו הסיכום והפלט להלן), ולכן ההפרשים בשורות אלה גדולים ואינם מעידים על שגיאת API.\n\n'
if note not in ap:
    ap = ap.replace('## 6. אימות מול הדוחות הרשמיים\n\n', '## 6. אימות מול הדוחות הרשמיים\n\n' + note, 1)
open(ap_path, 'w', encoding='utf-8').write(ap)

